from pathlib import Path
ROOT=Path('manuscript/ga1')

def rep(fn,old,new):
    p=ROOT/fn
    t=p.read_text(encoding='utf-8')
    n=t.count(old)
    if n!=1: raise SystemExit(f'{fn}: expected block once, got {n}: {old[:100]!r}')
    p.write_text(t.replace(old,new,1),encoding='utf-8')

rep('050-다섯-번째-답은-없다-v1.md', '''그래서 그는 결과가 아니라 조건을 적었다.\n\n백색 도크 시민 작업자.\n\n유노 조의 독립 전선.\n\n중립 증인.\n\n네라·미아·카라의 별도 중지권.\n\n세 명 사망.\n\n부상.\n\n07호 영구 냉각성능 저하.\n\n상호보증 부채.\n\n세린 감사권 제한.\n\n카라 배분권 심사.\n\n유노 외부배치.\n\n자기 개인책임.''', '''그래서 그는 결과가 아니라 조건을 적었다. 백색 도크 시민 작업자와 유노 조의 독립 전선, 중립 증인, 네라·미아·카라의 별도 중지권이 있었다. 그 대가로 세 명이 죽고 부상자가 나왔으며, 07호는 냉각성능을 영구적으로 잃었다. 상호보증 부채, 세린의 감사권 제한, 카라의 배분권 심사, 유노의 외부배치와 리안 자신의 개인책임도 함께 남았다.''')

rep('067-위험을-고르는-사람-v1.md', '''병동 기술자들이 옆에서 각 부품 이력을 붙였다.\n\n어느 멤브레인 로트인지.\n\n어느 전원부에서 시험했는지.\n\n소독방법.\n\n절연저항.\n\n버전.\n\n신호변환 규칙.\n\n실패한 시험도 같은 줄에 남았다.''', '''병동 기술자들은 각 부품의 멤브레인 로트와 시험 전원부, 소독방법, 절연저항, 버전, 신호변환 규칙을 붙였다. 실패한 시험도 성공기록과 같은 줄에 남겼다.''')
rep('067-위험을-고르는-사람-v1.md', '''“여기서 배운 거.”\n\n네라가 말했다.\n\n첫째, 전기적으로 맞는다는 것과 임상적으로 맞는다는 건 다르다.\n\n둘째, 숨은 과거 프로토콜을 모르면 ‘정상 응답’이 위험 신호일 수 있다.\n\n셋째, 리셋을 거부하는 장치를 오류로만 보고 더 강하게 밀면 피드백이 커질 수 있다.\n\n넷째, 버전과 환자 상태를 빼고 회로만 복사하면 같은 설계가 아니다.''', '''“여기서 배운 거.”\n\n네라가 말했다.\n\n“전기적으로 맞는다는 것과 임상적으로 맞는다는 건 달라요. 숨은 과거 프로토콜을 모르면 정상 응답이 오히려 위험 신호일 수 있고, 리셋 거부를 단순 오류로 보고 더 세게 밀면 피드백이 커져요. 버전과 환자 상태를 빼고 회로만 복사하면 같은 설계도 아니고.”''')

rep('073-남은-날짜는-서른-v1.md', '''리안도 아주 잠깐 같은 생각을 했다.\n\n끝난다.\n\n학생을 죄수처럼 묶어 두던 학원.\n\n사람을 평가자산으로 분류하고,\n\n배치와 치료와 기록을 거래하던 곳.\n\n그 구조가 삼십 일 뒤 무너진다.\n\n그렇다면 이건 기회일 수 있었다.\n\n리안은 미래에서 수많은 요새를 함락했다.\n\n적의 통제중심을 부수면 길이 열렸다.\n\n학원도 비슷하게 보였다.''', '''리안도 아주 잠깐 같은 생각을 했다. 학생을 죄수처럼 묶고 사람을 평가자산으로 분류하며 배치와 치료, 기록을 거래하던 구조가 삼십 일 뒤 무너진다. 그렇다면 끝이 아니라 기회일 수도 있었다.\n\n미래에서 수많은 요새를 함락한 리안에게는 통제중심을 부수면 길이 열린다는 경험이 있었다. 학원도 순간 그렇게 보였다.''')

# Ensure core facts remain.
checks={
 '050-다섯-번째-답은-없다-v1.md':['세 명이 죽','07호는 냉각성능','유노의 외부배치','개인책임'],
 '067-위험을-고르는-사람-v1.md':['멤브레인 로트','절연저항','숨은 과거 프로토콜','버전과 환자 상태'],
 '073-남은-날짜는-서른-v1.md':['삼십 일 뒤','평가자산','통제중심']
}
for fn,needles in checks.items():
    t=(ROOT/fn).read_text(encoding='utf-8')
    for needle in needles:
        if needle not in t: raise SystemExit(f'{fn}: required meaning lost: {needle}')
print('medium-breath reflow applied safely')
